export function toE164(raw: string): string | null {
  const compact = raw.trim().replace(/[\s().-]/g, '');
  let e164 = compact;
  if (!compact.startsWith('+')) {
    e164 = /^1?\d{10}$/.test(compact) ? `+${compact.length === 10 ? '1' : ''}${compact}` : '';
  }
  return E164.test(e164) ? e164 : null;
}

