    theme = 'Rest & Reflection';
    description = 'A season for going inward and preparing for renewal.';
    const winterYear = month === 11 ? year : year - 1;
    startDate = `${winterYear}-12-01`;
    endDate = `${winterYear + 1}-02-28`;
