  promise: Promise<T>,
  errorMapper?: (e: unknown) => E
): Promise<Result<T, E>> {
  try {
    const value = await promise;
    return ok(value);
  } catch (e) {
    const error = errorMapper ? errorMapper(e) : (e as E);
    return err(error);
  }
}

